a9m(a){return"Show all "+a+" holdings"},
aKU(a){return"Show all "+a+" positions"},
aKV(a){return"Show all "+a+" watchlist stocks"},
ga9n(){return"Show the header and tabs again"},
ga9o(){return"Show less"},
gaKW(){return"Simple avg P/E"},
gaKX(){return"Small Cap (<$2B)"},
aKY(a,b,c){return b+" \xb7 "+c+" shares"+a},
aKZ(a){return"Sold "+a},
